function fillTemplate(str, v){
  return String(str||"").replace(/\{(\w+)\}/g, (m,k)=> (v && v[k]!=null && v[k]!=="") ? String(v[k]) : (m==="{closing}" ? "the scheduled closing date" : ""));
}
function todoBlock(lead, short){
  const open = (Array.isArray(lead && lead.borrowerTodos) ? lead.borrowerTodos : []).filter(x=>x && x.t && !x.done);
  if(!open.length) return "";
  if(short) return " Still need from you: " + open.map(x=>x.t).join(", ") + ".";
  return "\n\nStill outstanding on my end, whenever you get a chance:\n" + open.map(x=>"  \u2022 "+x.t).join("\n");
}
function emailVars(lead, agentName){
  const full  = String(lead.name||lead.borrower||"").trim();
  const first = full.split(/[\s&]+/)[0] || "there";
  const addr  = [lead.address, [lead.city,[lead.state,lead.zip].filter(Boolean).join(" ")].filter(Boolean).join(", ")].filter(Boolean).join(", ");
  const ag    = String(agentName||lead.realtorAgent||"").trim();
  return { first, borrower: full, address: addr || "your new home",
    todos: todoBlock(lead, false), todosShort: todoBlock(lead, true),
    agent: ag, agentFirst: ag.split(/\s+/)[0] || "there",
    closing: lead.closingDate ? new Date(lead.closingDate+"T12:00:00").toLocaleDateString("en-US",{month:"long",day:"numeric"}) : "" };
}
function isMobileUA(){ try { return /iPhone|iPad|iPod|Android/i.test((navigator&&navigator.userAgent)||""); } catch { return false; } }
function outlookHref(to, subject, body){
  const q = `to=${encodeURIComponent(to||"")}&subject=${encodeURIComponent(subject||"")}&body=${encodeURIComponent(body||"")}`;
  return isMobileUA() ? `ms-outlook://compose?${q}` : `https://outlook.office.com/mail/deeplink/compose?${q}`;
}
