function MilestoneEmail({T, lead, agent, milestones={}, onClose}){
  const ORDER = Object.keys(MILESTONE_EMAILS);
  const reached = ORDER.filter(id=>typeof milestones[id]==="string" && milestones[id]);
  const latest  = reached.length ? reached[reached.length-1] : ORDER[0];
  const [msId,setMsId] = useState(latest);
  const [who,setWho]   = useState(agent && (agent.email||agent.phone) ? "both" : "borrower");
  const v = emailVars(lead, agent && agent.name);
  const [mode,setMode] = useState("email");   // email | text
  const tplFor = (aud) => {
    const e = MILESTONE_EMAILS[msId] || MILESTONE_EMAILS[ORDER[0]];
    if(mode==="text"){
      const raw = fillTemplate(aud==="agent" ? e.at : e.bt, v);
      return { subject:"", body: raw + (aud==="borrower" ? fillTemplate("{todosShort}", v) : "") };
    }
    const src = aud==="agent" ? e.a : e.b;
    return { subject: fillTemplate(src.s, v), body: fillTemplate(src.t, v) + EMAIL_SIGNATURE };
  };
  const [edited,setEdited] = useState({});
  const key = (aud)=>`${msId}|${aud}|${mode}`;
  const get = (aud) => edited[key(aud)] || tplFor(aud);
  const setField = (aud,f2,val) => setEdited(p=>({...p,[key(aud)]:{...get(aud),[f2]:val}}));
  const audiences = who==="both" ? ["borrower","agent"] : [who];
  const addrFor = (aud) => mode==="text"
    ? (aud==="agent" ? (agent&&agent.phone||"") : (lead.phone||""))
    : (aud==="agent" ? (agent&&agent.email||"") : (lead.email||""));
  const mailto = (aud) => { const g=get(aud); const to=addrFor(aud);
    if(mode==="text") return `sms:${String(to).replace(/[^0-9+]/g,"")}?&body=${encodeURIComponent(g.body)}`;
    return `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(g.subject)}&body=${encodeURIComponent(g.body)}`; };
  const outlook = (aud) => { const g=get(aud); return outlookHref(addrFor(aud), g.subject, g.body); };
  const copy = (aud) => { const g=get(aud);
    try{ navigator.clipboard.writeText(`${g.subject}\n\n${g.body}`); if(window.__flashSync) window.__flashSync("✓ Email copied"); }catch{} };
  const lb={fontSize:9,fontWeight:800,color:T.muted,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:5};
  const chip=(on)=>({background:on?T.navy:"transparent",border:`1px solid ${on?T.navy:T.border}`,borderRadius:8,padding:"7px 12px",color:on?"#fff":T.text2,fontWeight:800,fontSize:11,cursor:"pointer"});
  const inp={boxSizing:"border-box",width:"100%",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"9px 11px",color:T.text,fontSize:12.5,outline:"none"};
  return (
    <div onClick={onClose} style={{position:"fixed",inset:0,zIndex:460,background:"rgba(8,10,16,0.75)",display:"flex",alignItems:"center",justifyContent:"center",padding:"calc(14px + env(safe-area-inset-top)) 14px calc(14px + env(safe-area-inset-bottom))"}}>
      <div onClick={e=>e.stopPropagation()} style={{background:T.card,borderRadius:16,width:"100%",maxWidth:560,maxHeight:"92vh",overflowY:"auto",border:`1px solid ${T.border}`}}>
        <div style={{background:T.navy,borderRadius:"16px 16px 0 0",padding:"14px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",position:"sticky",top:0,zIndex:5}}>
          <div>
            <div style={{fontSize:9,color:"rgba(255,255,255,0.7)",fontWeight:800,letterSpacing:"0.12em",textTransform:"uppercase"}}>Milestone Update</div>
            <div style={{fontSize:16,fontWeight:900,color:"#fff",marginTop:2}}>{fmtName(lead.name||lead.borrower)}</div>
          </div>
          <button onClick={onClose} style={{background:"rgba(255,255,255,0.1)",border:"none",color:"#fff",borderRadius:8,padding:"6px 12px",cursor:"pointer",fontSize:16}}>×</button>
        </div>
        <div style={{padding:18,display:"flex",flexDirection:"column",gap:14}}>
          <div style={{display:"flex",gap:7}}>
            {[["email","✉ Email"],["text","💬 Text"]].map(([k,l])=>(
              <button key={k} onClick={()=>setMode(k)} style={{...chip(mode===k),flex:1}}>{l}</button>
            ))}
          </div>
          <div>
            <div style={lb}>Milestone</div>
            <select value={msId} onChange={e=>setMsId(e.target.value)} style={{...inp,fontWeight:700,cursor:"pointer"}}>
              {ORDER.map(id=>(<option key={id} value={id}>{MILESTONE_EMAILS[id].label}{milestones[id]?` · ${fmtDate(milestones[id])}`:" (not stamped)"}</option>))}
            </select>
          </div>
          <div>
            <div style={lb}>Send to</div>
            <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
              <button onClick={()=>setWho("borrower")} style={chip(who==="borrower")}>Borrower</button>
              <button onClick={()=>setWho("agent")} disabled={!agent} style={{...chip(who==="agent"),opacity:agent?1:0.4}}>Agent{agent?` · ${String(agent.name).split(" ")[0]}`:""}</button>
              <button onClick={()=>setWho("both")} disabled={!agent} style={{...chip(who==="both"),opacity:agent?1:0.4}}>Both</button>
            </div>
            {!agent&&<div style={{fontSize:9.5,color:T.ghost,marginTop:6,lineHeight:1.5}}>No partner record matches this file's agent, so only the borrower version is available.</div>}
          </div>
          {audiences.map(aud=>{
            const g=get(aud); const to=addrFor(aud);
            return (
              <div key={aud} style={{background:T.inner,borderRadius:12,padding:"12px 13px"}}>
                <div style={{display:"flex",alignItems:"baseline",gap:8,marginBottom:8}}>
                  <span style={{fontSize:9,fontWeight:800,color:T.gold,letterSpacing:"0.08em",textTransform:"uppercase"}}>{aud==="agent"?"To the agent":"To the borrower"}</span>
                  <span style={{marginLeft:"auto",fontSize:10,color:to?T.muted:T.red,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:200}}>{to||"no email on file"}</span>
                </div>
                {mode==="email"&&(<>
                  <div style={lb}>Subject</div>
                  <input value={g.subject} onChange={e=>setField(aud,"subject",e.target.value)} style={{...inp,fontWeight:700,marginBottom:9}}/>
                </>)}
                <div style={lb}>{mode==="text"?"Text message":"Message"}</div>
                <textarea value={g.body} onChange={e=>setField(aud,"body",e.target.value)} rows={mode==="text"?5:11} style={{...inp,resize:"vertical",lineHeight:1.55,fontSize:12}}/>
                {mode==="text"&&<div style={{fontSize:9,color:g.body.length>320?T.red:T.ghost,fontWeight:700,marginTop:4}}>{g.body.length} characters {g.body.length>320?"— will send as multiple texts":""}</div>}
                <div style={{display:"flex",gap:7,marginTop:9,flexWrap:"wrap"}}>
                  {mode==="email"&&<a href={outlook(aud)} style={{flex:1,textAlign:"center",background:to?"#0F6CBD":T.border,borderRadius:8,padding:"10px 0",color:to?"#fff":T.muted,fontWeight:800,fontSize:12,textDecoration:"none",pointerEvents:to?"auto":"none"}}>Open in Outlook</a>}
                  <a href={mailto(aud)} style={{flex:1,textAlign:"center",background:to?(mode==="text"?T.navy:"transparent"):T.border,border:mode==="email"?`1px solid ${T.border}`:"none",borderRadius:8,padding:mode==="email"?"9px 0":"10px 0",color:to?(mode==="text"?"#fff":T.text2):T.muted,fontWeight:800,fontSize:12,textDecoration:"none",pointerEvents:to?"auto":"none"}}>{mode==="text"?"Open in Messages":"Default mail"}</a>
                  <button onClick={()=>copy(aud)} style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:8,padding:"9px 14px",color:T.text2,fontWeight:800,fontSize:11.5,cursor:"pointer"}}>Copy</button>
                  {edited[key(aud)]&&<button onClick={()=>setEdited(p=>{const q={...p}; delete q[key(aud)]; return q;})} style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:8,padding:"9px 12px",color:T.muted,fontWeight:800,fontSize:11,cursor:"pointer"}}>Reset</button>}
                </div>
              </div>
            );
          })}
          <div style={{fontSize:9,color:T.ghost,lineHeight:1.6}}>Written to sit alongside the automated status emails NAF already sends — these add the detail those can’t: your dates, your property, and what’s actually outstanding. Everything sends from your own address, so replies come to you.</div>
        </div>
      </div>
    </div>
  );
}

// ═══════════ REFI RADAR ENGINE ═══════════
// Everything here runs on data already in the CRM: original amount, note rate, closing date.
// No credit pull, no bureau feed — amortization + an appreciation assumption you control.
function mortPmt(P, annualPct, nMonths){
  P = Number(P)||0; nMonths = Number(nMonths)||0;
  if(!P || nMonths<=0) return 0;
  const r = (Number(annualPct)||0)/100/12;
  if(r<=0) return P/nMonths;
  const f = Math.pow(1+r, nMonths);
  return P*r*f/(f-1);
}
function amortBalance(P, annualPct, nMonths, monthsPaid){
  P = Number(P)||0; nMonths = Number(nMonths)||0; monthsPaid = Number(monthsPaid)||0;
  if(!P || nMonths<=0) return P;
  if(monthsPaid<=0) return P;
  if(monthsPaid>=nMonths) return 0;
  const r = (Number(annualPct)||0)/100/12;
  if(r<=0) return P*(1-monthsPaid/nMonths);
  const f = Math.pow(1+r,nMonths), g = Math.pow(1+r,monthsPaid);
  return P*(f-g)/(f-1);
}
function monthsElapsed(iso, now){
  if(!iso) return 0;
  const d = new Date(String(iso).slice(0,10)+"T12:00:00");
  if(isNaN(d.getTime())) return 0;
  const m = (now.getFullYear()-d.getFullYear())*12 + (now.getMonth()-d.getMonth()) - (now.getDate()<d.getDate() ? 1 : 0);
  return Math.max(0, m);
}
// A KHC bond loan refinances into its underlying program, so KHC maps to FHA/Conventional.
function refiTypeKey(t){
  const x = String(t||"").toUpperCase();
  if(/JUMBO/.test(x)) return "Jumbo";
  if(/NON.?QM/.test(x)) return "Non-QM";
  if(/USDA|RURAL/.test(x)) return "USDA";
  if(/\bVA\b/.test(x)) return "VA";
  if(/FHA/.test(x)) return "FHA";
  return "Conventional";
}
function refiOpportunity(loan, o){
  const now      = o.now || new Date();
  const term     = Number(loan.termMonths)||360;
  const paid     = monthsElapsed(loan.closingDate, now);
  const orig     = Number(loan.amount||loan.loanAmount)||0;
  const rate     = Number(loan.rate)||0;
  const mkt      = Number(o.marketRate)||0;
  const costs    = Number(o.costs)||0;
  const balance  = amortBalance(orig, rate, term, paid);
  const remaining= Math.max(1, term - paid);
  const curPmt   = mortPmt(orig, rate, term);
  const newTerm  = o.matchTerm ? remaining : 360;
  const financed = balance + (o.rollCosts ? costs : 0);
  const newPmt   = mortPmt(financed, mkt, newTerm);
  const monthly  = curPmt - newPmt;
  const basis    = Number(loan.purchasePrice)||Number(loan.appraisedValue)||(orig ? orig/0.9 : 0);
  const value    = basis * Math.pow(1 + (Number(o.apprPct)||0)/100, paid/12);
  const equity   = Math.max(0, value - balance);
  const ltv      = value>0 ? balance/value*100 : 0;
  return { term, paid, balance, remaining, curPmt, newPmt, newTerm, financed, monthly,
    yr3:monthly*36, yr5:monthly*60, yr10:monthly*120, value, equity, ltv,
    breakEven: monthly>0 ? costs/monthly : null, rateDrop: rate-mkt, rate, orig };
}

// ═══════════ DEMO MODE ═══════════
// Live at #/demo on the SAME deployment as the real CRM, so every feature ships to the demo
// automatically. Demo never touches Supabase: getSupabase() returns null, so all persistence
// no-ops, visitors play with generated data in memory, and a refresh resets the world.
const IS_DEMO = typeof window!=="undefined" && /^#\/demo/.test(window.location.hash||"");
const DEMO_TEAM = ["Jordan Maxwell","Carla (LP1)","Devin (LP2)","Sonia (LP3)"];   // demo branch: BM + loan partners (declared before demoData() runs)
function demoData(){
  let sd = 20260729;                                        // deterministic: same book every load
  const rnd = () => { sd|=0; sd=(sd+0x6D2B79F5)|0; let t=Math.imul(sd^(sd>>>15),1|sd); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; };
  const pick = a => a[Math.floor(rnd()*a.length)];
  const FIRST=["Wyatt","Harper","Silas","Nora","Beckett","June","Dalton","Ivy","Rhett","Callie","Emmett","Sadie","Knox","Willa","Tucker","Lena","Brooks","Opal","Cash","Marlowe","Judd","Tessa","Colt","Rosie","Levi","Maren","Duke","Hattie","Reid","Clara","Boone","Elsie","Gus","Piper","Waylon","Ruthie","Amos","Lacey","Shep","Vera"];
  const LAST=["Caudill","Whitaker","Prewitt","Ballard","Hensley","McCoy","Slone","Tackett","Gabbard","Ratliff","Stamper","Burdette","Combs2","Sizemore","Napier","Fugate","Couch","Begley","Hoskins","Asher","Sparks","Turner2","Bowling","Feltner","Eversole","Deaton","Cornett","Wooton","Mullins","Halcomb"].map(x=>x.replace(/2$/,""));
  const CITIES=[["Lexington","40509"],["Richmond","40475"],["Nicholasville","40356"],["Danville","40422"],["Somerset","42501"],["London","40741"],["Berea","40403"],["Georgetown","40324"],["Winchester","40391"],["Lancaster","40444"],["Harrodsburg","40330"],["Mount Vernon","40456"]];
  const STREETS=["Redbud Ln","Saddlebrook Dr","Limestone Ct","Bluegrass Pkwy","Foxglove Way","Harvest Ridge","Cedar Hollow Rd","Meadowlark Dr","Stonegate Blvd","Trailside Ct","Juniper Bend","Old Mill Rd"];
  const nm=()=>`${pick(FIRST)} ${pick(LAST)}`;
  const cpl=()=>{ const l=pick(LAST); return `${pick(FIRST)} & ${pick(FIRST)} ${l}`; };
  const ph=()=>`(859) 555-${String(1000+Math.floor(rnd()*9000))}`;
  const addr=()=>{ const [c,z]=pick(CITIES); return {address:`${100+Math.floor(rnd()*880)} ${pick(STREETS)}`, city:c, state:"KY", zip:z}; };
  const AGENTS=[["Paige Sutton","eXp Realty"],["Marcus Bell","Keller Williams Legacy"],["Deana Frye","RE/MAX Creekside"],["Tyler Nance","Century 21 Advantage"],["Robin Castle","Bluegrass Sotheby’s"],["Chad Osborne","United Real Estate"],["Kendra Lyons","Rector Hayden"],["Vince Marsh","Coldwell Banker McMahan"],["Abby Sturgill","Weichert Ford Brothers"],["Grant Pearl","EXIT Realty Crutcher"],["Mia Renfro","Keller Williams Commonwealth"],["Doyle Hacker","Turf Town Properties"]];
  const TYPES=["Conventional","Conventional","Conventional","FHA","FHA","USDA","VA","KHC FHA","KHC Conventional","Jumbo"];
  const amt=(t)=> t==="Jumbo" ? 780000+Math.floor(rnd()*40)*5000 : 245000+Math.floor(rnd()*50)*5000;   // averages ~$400K across the book
  const iso=(y,m,d)=>`${y}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
  const NOW=new Date(); const Y=NOW.getFullYear(), M=NOW.getMonth()+1;
  // ── Production tracker: last year = 300 units / $100M; this year pacing the same ──
  const prodMonths=[];
  // Climbing history since 2015: [years back, units, exact annual volume]
  const CLIMB=[[11,68,13200000],[10,84,17500000],[9,101,22800000],[8,118,28600000],[7,135,35400000],[6,168,48900000],[5,196,61700000],[4,205,70200000],[3,218,79400000],[2,232,88600000],[1,250,100000000]];
  CLIMB.forEach(([back,u,vol])=>{ const y2=Y-back, per=Math.floor(u/12), extra=u%12;
    let vLeft=vol;
    for(let i2=0;i2<12;i2++){ const um=per+(i2<extra?1:0); const v=i2===11?vLeft:Math.round(um*(vol/u)/1000)*1000; vLeft-=v;
      prodMonths.push({month:iso(y2,i2+1,1).slice(0,7), volume:v, units:um, seconds:0, pulls:Math.max(8,Math.round(um*1.35))}); } });
  for(let i=1;i<M;i++){ const u=19+Math.floor(rnd()*4);
    prodMonths.push({month:iso(Y,i,1).slice(0,7), volume:u*(392000+Math.floor(rnd()*9)*2000), units:u, seconds:0, pulls:26+Math.floor(rnd()*10)}); }
  // ── Partners ──
  const partners=AGENTS.map(([n,b],i)=>{ const units=i<3?34-i*4:6+Math.floor(rnd()*16);
    return { id:"dp"+i, name:n, brokerage:b, units, deals:units, funded:units, volume:units*(315000+Math.floor(rnd()*12)*3000), unique_clients:units-Math.floor(rnd()*3), portalOn:false, portalCap:0, portalTypes:"", portalDays:90, email:"", phone:ph(), photoUrl:"", portalSlug:"", portalPin:"" }; });
  const agentName=()=>pick(AGENTS)[0];
  // ── Milestone builders keyed to stage depth ──
  const msFor=(stage,cd)=>{ const out={}; const d=new Date(cd+"T12:00:00");
    const back=(days)=>{ const x=new Date(d); x.setDate(x.getDate()-days); return x.toISOString().slice(0,10); };
    const SEQ=[["underContract",42],["disclosuresRequested",40],["disclosuresSigned",37],["sentToScrub",34],["sentToSetup",30],["sentToProcessing",24],["sentToUW",15],["uwApproval",8],["clearToClose",4]];
    const depth={contacted:3,scrub:4,setup:5,processing:6,ctc:9,onhold:5,closed:9}[stage]||0;
    SEQ.slice(0,depth).forEach(([id,ago])=>{ out[id]=back(ago); });
    if(depth>=6){ out.appraisalOrdered=back(28); if(depth>=7||rnd()>0.4) out.appraisalReceived=back(18); }
    return out; };
  // ── Active pipeline: ~38 files closing this month + next ──
  const STG=["contacted","contacted","scrub","setup","setup","processing","processing","processing","ctc","ctc"];
  const leads=[]; let idn=1000;
  for(let i=0;i<38;i++){ const t=pick(TYPES), a=amt(t), stage=pick(STG);
    const daysLeft = 28 - NOW.getDate();
    const nextMo = daysLeft < 3 ? true : rnd()>0.45;
    const cm = nextMo ? (M===12?1:M+1) : M, cy = nextMo&&M===12 ? Y+1 : Y;
    const cd = iso(cy,cm, nextMo ? 2+Math.floor(rnd()*26) : Math.min(28, NOW.getDate()+1+Math.floor(rnd()*Math.max(1,daysLeft))));
    const ag=agentName(); const A2=addr();
    leads.push({ id:"D"+(idn++), name: rnd()>0.5?cpl():nm(), phone:ph(), email:"", source:ag, realtorAgent:ag,
      loanType:t, loanPurpose: rnd()>0.85?"Refinance":"Purchase", loanAmount:a, amount:a, purchasePrice:Math.round(a/0.9/1000)*1000,
      rate: [5.99,6.125,6.25,6.375,6.49,6.625][Math.floor(rnd()*6)],
      ...(()=>{ const locked = rnd()>0.4;                            // ~60% of active files carry a lock
        if(!locked) return {rateLocked:false, lockExpiry:""};
        const x=new Date(NOW); x.setDate(x.getDate()+3+Math.floor(rnd()*27));
        return {rateLocked:true, lockExpiry:x.toISOString().slice(0,10)}; })(),
      stage, assignee: pick(DEMO_TEAM),
      assignedAck:true, priority: i<3, closingDate:cd, milestones: msFor(stage,cd), ...A2,
      notes:[{author:pick(DEMO_TEAM), text:pick(["Appraisal scheduled for next week.","Waiting on updated paystub.","Title work ordered.","Insurance quote in \u2014 binding today.","Docs out to borrower.","Cleared two conditions this morning."]), time:"7/22/26 · 10:14 AM"}],
      borrowerTodos: rnd()>0.7?[{t:"Last 2 bank statements",done:false},{t:"Updated paystub",done:false}]:[],
      createdAt: iso(Y, Math.max(1,M-2), 1+Math.floor(rnd()*27)) }); }
  // ── New Loans triage ──
  const NEWST=["Offer Submitted","Numbers Sent","Numbers Sent","W for Docs","W for Docs","W for App","Other"];
  for(let i=0;i<11;i++){ const t=pick(TYPES), a=amt(t), ag=agentName();
    leads.push({ id:"D"+(idn++), name: rnd()>0.5?cpl():nm(), phone:ph(), email:"", source: rnd()>0.5?ag:pick(["Zillow","Past Client","Referral \u2014 friend"]),
      realtorAgent:"", loanType:t, loanPurpose:"Purchase", loanAmount:a, amount:a, stage:"new", newStatus:pick(NEWST),
      assignee:"", assignedAck:true, priority:false, milestones:{}, notes:[], borrowerTodos:[],
      createdAt: iso(Y,M,Math.max(1,NOW.getDate()-Math.floor(rnd()*9))) }); }
  // ── Funded book in the CRM: this month + five prior, ~25/mo pace ──
  const loans=[];
  for(let mo=0; mo<6; mo++){ const mm=M-mo, y2=mm<1?Y-1:Y, m2=((mm-1)%12+12)%12+1;
    const count = mo===0 ? Math.min(20, Math.max(5, NOW.getDate()-6)) : 19+Math.floor(rnd()*5);
    for(let i=0;i<count;i++){ const t=pick(TYPES), a=amt(t), ag=agentName(); const A2=addr();
      const cd=iso(y2,m2,1+Math.floor(rnd()*(mo===0?Math.max(1,NOW.getDate()-1):27)));
      loans.push({ id:"F"+(idn++), borrower: rnd()>0.5?cpl():nm(), name:"", phone:ph(), email:"", loanType:t,
        amount:a, loanAmount:a, purchasePrice:Math.round(a/0.9/1000)*1000, rate:[5.875,6.0,6.125,6.25,6.375,6.5][Math.floor(rnd()*6)],
        stage:"closed", closingDate:cd, realtorAgent:ag, source:ag, titleCompany:pick(["Bluegrass Land Title","Central KY Title","First Southern Title"]),
        loanNumber:String(7100000+Math.floor(rnd()*899999)), milestones:msFor("closed",cd), ...A2, notes:[], createdAt:cd }); } }
  // ── Historical funded records (slim) — the Analytics yearly table counts CRM files ──
  CLIMB.filter(([back])=>back>=2).forEach(([back,u,vol])=>{ const y2=Y-back, avg=vol/u;
    for(let i2=0;i2<u;i2++){ const a2=Math.round(avg*(0.78+rnd()*0.44)/1000)*1000;
      loans.push({ id:`H${y2}_${i2}`, borrower: rnd()>0.5?cpl():nm(), name:"", phone:"", email:"", loanType:pick(TYPES),
        amount:a2, loanAmount:a2, purchasePrice:0, rate:0, stage:"closed", closingDate:iso(y2,1+Math.floor(rnd()*12),1+Math.floor(rnd()*27)),
        realtorAgent:agentName(), source:"", titleCompany:"", loanNumber:String(6000000+Math.floor(rnd()*999999)),
        milestones:{}, address:"", city:"", state:"", zip:"", notes:[], createdAt:"" }); } });
  { const [ , u, vol]=CLIMB[CLIMB.length-1]; const y2=Y-1, avg=vol/u;   // last year gets its full 250
    for(let i2=0;i2<u;i2++){ const a2=Math.round(avg*(0.78+rnd()*0.44)/1000)*1000;
      loans.push({ id:`H${y2}_${i2}`, borrower: rnd()>0.5?cpl():nm(), name:"", phone:"", email:"", loanType:pick(TYPES),
        amount:a2, loanAmount:a2, purchasePrice:0, rate:0, stage:"closed", closingDate:iso(y2,1+Math.floor(rnd()*12),1+Math.floor(rnd()*27)),
        realtorAgent:agentName(), source:"", titleCompany:"", loanNumber:String(6000000+Math.floor(rnd()*999999)),
        milestones:{}, address:"", city:"", state:"", zip:"", notes:[], createdAt:"" }); } }
  // ── Team tasks ──
  const tasks=[
    {id:"t1", title:"Order appraisal \u2014 Whitaker file", assignee:"Carla (LP1)", createdBy:"Jordan Maxwell", dueDate:iso(Y,M,Math.min(28,NOW.getDate()+1)), done:false},
    {id:"t2", title:"Chase title work \u2014 Ballard", assignee:"Devin (LP2)", createdBy:"Jordan Maxwell", dueDate:iso(Y,M,Math.min(28,NOW.getDate()+2)), done:false},
    {id:"t3", title:"VOE follow-up \u2014 Hensley", assignee:"Sonia (LP3)", createdBy:"Jordan Maxwell", dueDate:iso(Y,M,Math.min(28,NOW.getDate()+2)), done:false},
    {id:"t4", title:"Send updated numbers \u2014 McCoy", assignee:"Jordan Maxwell", createdBy:"Carla (LP1)", dueDate:iso(Y,M,Math.min(28,NOW.getDate()+3)), done:false},
    {id:"t5", title:"Lock expirations audit", assignee:"Jordan Maxwell", createdBy:"Jordan Maxwell", dueDate:iso(Y,M,Math.min(28,NOW.getDate()+4)), done:true},
  ];
  // ── P&L entries for the current month (calculator history feel) ──
  const pnlEntries=[]; const PRD=["Conventional","FHA","USDA","VA","KHC","Conventional","Conventional","FHA"];
  for(let i=0;i<14;i++){ const p2=pick(PRD); const a=amt(p2==="Jumbo"?"Jumbo":"Conventional");
    const bps={Conventional:150,FHA:250,USDA:250,VA:200,KHC:100}[p2]||150;
    pnlEntries.push({ id:"pe"+i, month:iso(Y,M,1).slice(0,7), name:nm(), product:p2, comp:"Full Comp", amount:a,
      branch:Math.round(a*bps/10000)+1995-995, lo:Math.round(a*0.01), concession:0, funded:true }); }
  // Estimated-to-close next month: the real pipeline files feeding the P&L as unfunded entries
  { const nY = M===12?Y+1:Y, nM = M===12?1:M+1, nKey = iso(nY,nM,1).slice(0,7);
    const prodOf = t2 => /KHC/i.test(t2)?"KHC":/FHA/i.test(t2)?"FHA":/USDA/i.test(t2)?"USDA":/\bVA\b/i.test(t2)?"VA":/Jumbo/i.test(t2)?"Jumbo":/Non/i.test(t2)?"NonQM":"Conventional";
    const BPS={Conventional:150,FHA:250,USDA:250,VA:200,KHC:100,Jumbo:100,NonQM:100};
    leads.filter(l=>l.stage!=="new"&&String(l.closingDate||"").startsWith(nKey)).slice(0,18).forEach((l,i2)=>{
      const p2=prodOf(l.loanType), a2=l.loanAmount||0;
      pnlEntries.push({ id:"pest"+i2, month:nKey, name:l.name, product:p2, comp:"Full Comp", amount:a2,
        branch:Math.round(a2*(BPS[p2]||150)/10000)+1995-995, lo:Math.round(a2*0.01), concession:0, funded:false }); }); }
  const pnlMonths=[];
  for(let i=1;i<M;i++){ const u=19+Math.floor(rnd()*4);
    pnlMonths.push({month:iso(Y,i,1).slice(0,7), branch:Math.round(u*(400000*0.016)), lo:Math.round(u*400000*0.01), units:u, cost:13333}); }
  return {leads, loans, partners, tasks, prodMonths, pnlEntries, pnlMonths};
}
