// ─── AUTH ───
// "off" = profile picker, no password (current behavior — nobody can be locked out)
// "on"  = real logins required. Flip this ONLY after accounts exist in Supabase.
const AUTH_MODE = "off";
async function authSession(){
  try { const sb = await getSupabase(); if(!sb) return null; const { data } = await sb.auth.getSession(); return data?.session || null; } catch { return null; }
}
async function authSignIn(email, password){
  const sb = await getSupabase(); if(!sb) throw new Error("No connection");
  const { data, error } = await sb.auth.signInWithPassword({ email: String(email).trim(), password });
  if (error) throw error;
  return data?.session || null;
}
async function authSignOut(){ try { const sb = await getSupabase(); if(sb) await sb.auth.signOut(); } catch {} }
async function authProfile(userId){
  try {
    const sb = await getSupabase(); if(!sb) return null;
    const { data, error } = await sb.from("profiles").select("*").eq("id", userId).maybeSingle();
    if (error) return null;
    return data || null;
  } catch { return null; }
}

