// ─── THEME DECORATIONS (festive overlays) ─────────────────────────────────────
function ThemeDecor({decor}) {
  if(!decor) return null;
  // Minimal, calm decorations: a few corner-anchored elements with a slow gentle drift.
  // No falling streams or busy animation — present, not distracting.
  const SETS={
    flags:        [{e:"🇺🇸",p:{top:66,left:10},s:22},{e:"🇺🇸",p:{top:66,right:10},s:22,d:1.5},{e:"🎆",p:{bottom:86,right:14},s:18,d:0.7}],
    halloween:    [{e:"🎃",p:{top:66,left:10},s:22},{e:"🐈‍⬛",p:{bottom:88,right:12},s:20,d:1.2},{e:"🦇",p:{top:64,right:12},s:16,d:0.6},{e:"🕸️",p:{bottom:86,left:12},s:15,d:1.8,o:0.5}],
    thanksgiving: [{e:"🦃",p:{top:66,left:10},s:22},{e:"🍁",p:{top:64,right:12},s:18,d:1.1},{e:"🍂",p:{bottom:88,left:12},s:16,d:0.5},{e:"🌽",p:{bottom:88,right:12},s:17,d:1.6}],
    christmas:    [{e:"🎄",p:{top:66,left:10},s:22},{e:"🎅",p:{top:64,right:12},s:20,d:1.3},{e:"❄️",p:{bottom:88,left:12},s:15,d:0.6,o:0.6},{e:"🎁",p:{bottom:88,right:12},s:17,d:1.8}],
    valentines:   [{e:"💘",p:{top:66,right:12},s:22},{e:"💕",p:{top:64,left:12},s:16,d:1.2,o:0.7},{e:"💝",p:{bottom:88,left:12},s:16,d:0.5,o:0.7}],
    stpatricks:   [{e:"🎩",p:{top:66,left:10},s:22},{e:"☘️",p:{top:64,right:12},s:17,d:1.1},{e:"🪙",p:{bottom:88,right:12},s:16,d:0.6,o:0.8},{e:"🌈",p:{bottom:88,left:12},s:17,d:1.7,o:0.7}],
    easter:       [{e:"🐰",p:{top:66,left:10},s:22},{e:"🐣",p:{top:64,right:12},s:18,d:1.2},{e:"🌷",p:{bottom:88,left:12},s:16,d:0.5,o:0.8}],
    newyears:     [{e:"🎆",p:{top:60,left:"12%"},s:26,fade:true},{e:"🎇",p:{top:56,right:"12%"},s:24,fade:true,d:1.8},{e:"✨",p:{bottom:88,right:14},s:15,d:0.8,o:0.7}],
  };
  const items=SETS[decor];
  if(!items) return null;
  return (
    <div style={{position:"fixed",inset:0,zIndex:5,pointerEvents:"none",overflow:"hidden"}}>
      <style>{`
        @keyframes calmDrift{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-7px) rotate(2deg)}}
        @keyframes calmFade{0%{transform:scale(0.75);opacity:0}25%{opacity:0.55}70%{transform:scale(1.05);opacity:0.35}100%{transform:scale(1.15);opacity:0}}
      `}</style>
      {items.map((it,i)=>(
        <div key={i} style={{position:"absolute",...it.p,fontSize:it.s,opacity:it.o??0.85,animation:`${it.fade?"calmFade 6s ease-out":"calmDrift 6s ease-in-out"} ${it.d||0}s infinite`}}>{it.e}</div>
      ))}
    </div>
  );
}

// ─── TEAM TASKS — standalone to-dos assignable to anyone ──────────────────
function TeamTasksCard({tasks,currentUser,T,HL,onAdd,onToggle,onDelete}) {
  const [adding,setAdding]=useState(false);
  const [showWaiting,setShowWaiting]=useState(false);
  const [collapseMine,setCollapseMine]=useState(()=>{try{return localStorage.getItem(`collapseMine_${currentUser}`)==="1";}catch{return false;}});
  useEffect(()=>{try{localStorage.setItem(`collapseMine_${currentUser}`,collapseMine?"1":"0");}catch{}},[collapseMine,currentUser]);
  const [title,setTitle]=useState(""); const [who,setWho]=useState(currentUser||"Blake");
  const [due,setDue]=useState(""); const [note,setNote]=useState("");
  const mine=tasks.filter(t=>t.assignedTo===currentUser&&!t.done).sort((a,b)=>{ const ao=a.createdBy&&a.createdBy!==currentUser?0:1; const bo=b.createdBy&&b.createdBy!==currentUser?0:1; if(ao!==bo) return ao-bo; return (a.dueDate||"9999").localeCompare(b.dueDate||"9999"); });
  const byMe=tasks.filter(t=>t.createdBy===currentUser&&t.assignedTo!==currentUser&&!t.done);
  const doneRecent=tasks.filter(t=>t.done&&(t.assignedTo===currentUser||t.createdBy===currentUser)).slice(0,4);
  const submit=()=>{ if(!title.trim()) return; onAdd({title:title.trim(),assignedTo:who,dueDate:due,notes:note.trim()}); setTitle("");setDue("");setNote("");setAdding(false); };
  const fmtDue=d=>{ if(!d) return null; const dt=new Date(d+"T00:00"); const today=new Date(); today.setHours(0,0,0,0); const diff=Math.round((dt-today)/86400000); const s=dt.toLocaleDateString("en-US",{month:"short",day:"numeric"}); return {s, late:diff<0, today:diff===0}; };
  const Row=({t,mineRow})=>{ const d=fmtDue(t.dueDate); return (
    <div style={{display:"flex",alignItems:"flex-start",gap:8,padding:"6px 0",borderBottom:`1px solid ${T.border}`}}>
      <button onClick={()=>onToggle(t.id)} style={{width:19,height:19,borderRadius:6,flexShrink:0,marginTop:1,cursor:"pointer",background:t.done?HL.border:"transparent",border:t.done?"none":`1.5px solid ${T.muted}`,color:"#fff",fontSize:11,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center"}}>{t.done?"✓":""}</button>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:11.5,fontWeight:700,color:T.text,textDecoration:t.done?"line-through":"none",opacity:t.done?0.55:1}}>{t.title}</div>
        <div style={{fontSize:9.5,color:T.muted,marginTop:2}}>
          {mineRow?`from ${t.createdBy||"—"}`:`→ ${t.assignedTo}`}
          {d&&<span style={{color:d.late?"#c03030":d.today?"#b07a2a":T.muted,fontWeight:700}}> · {d.late?"OVERDUE ":d.today?"today · ":""}{d.s}</span>}
          {t.notes&&<span> · {t.notes}</span>}
        </div>
      </div>
      <button onClick={()=>onDelete(t.id)} style={{background:"none",border:"none",color:T.ghost,fontSize:13,cursor:"pointer",padding:"0 2px",flexShrink:0}}>×</button>
    </div>
  );};
  const [cardOpen,setCardOpen]=useState(()=>{try{const v=localStorage.getItem(`todoCardOpen_${currentUser}`); if(v!==null) return v==="1";}catch{} return currentUser!=="Blake";});
  useEffect(()=>{try{localStorage.setItem(`todoCardOpen_${currentUser}`,cardOpen?"1":"0");}catch{}},[cardOpen,currentUser]);
  const inp={width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"8px 10px",color:T.text,fontSize:12,outline:"none"};
  return (
    <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:12,padding:"13px 15px",marginBottom:10}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:cardOpen&&(mine.length||byMe.length||adding)?8:0}}>
        <div onClick={()=>setCardOpen(v=>!v)} style={{display:"flex",alignItems:"center",gap:7,cursor:"pointer",flex:1}}>
          <div style={{fontSize:10,color:T.text2,fontWeight:800,letterSpacing:"0.08em",textTransform:"uppercase"}}>☑ {currentUser} To-Do{mine.length>0&&<span style={{marginLeft:7,background:HL.border,color:HL.fg==="#e11d2e"?"#fff":HL.fg,borderRadius:9,padding:"1px 7px",fontSize:9,fontWeight:900}}>{mine.length}</span>}</div>
          <span style={{fontSize:10,color:T.ghost,transform:cardOpen?"rotate(90deg)":"none",transition:"transform 0.15s"}}>›</span>
        </div>
        {cardOpen&&<button onClick={()=>setAdding(a=>!a)} style={{background:"transparent",border:`1px solid ${HL.border}55`,borderRadius:6,padding:"3px 10px",color:HL.border,fontWeight:800,fontSize:10,cursor:"pointer"}}>{adding?"× Cancel":"+ Assign Task"}</button>}
      </div>
      {cardOpen&&<>
      {adding&&(
        <div style={{background:T.inner,borderRadius:10,padding:"11px 12px",display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
          <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="What needs done? e.g. Schedule the Smith closing" style={inp}/>
          <div style={{display:"flex",gap:8}}>
            <div style={{flex:1}}>
              <div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Assign To</div>
              <select value={who} onChange={e=>setWho(e.target.value)} style={{...inp,padding:"8px 8px"}}>
                {TEAM.map(n=><option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            <div style={{flex:1}}>
              <div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Due (optional)</div>
              <input type="date" value={due} onChange={e=>setDue(e.target.value)} style={{...inp,colorScheme:"light"}}/>
            </div>
          </div>
          <input value={note} onChange={e=>setNote(e.target.value)} placeholder="Notes (optional)" style={inp}/>
          <button onClick={submit} style={{background:T.navy,border:"none",borderRadius:8,padding:"9px 0",color:"#fff",fontWeight:800,fontSize:12,cursor:"pointer"}}>Assign to {who}</button>
        </div>
      )}
      {mine.length>0&&<>
        <button onClick={()=>setCollapseMine(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",width:"100%",background:"transparent",border:"none",cursor:"pointer",padding:"2px 0 1px"}}>
          <span style={{fontSize:8.5,color:T.muted,fontWeight:800,letterSpacing:"0.08em",textTransform:"uppercase"}}>Assigned to me ({mine.length})</span>
          <span style={{fontSize:10,color:T.ghost,transform:collapseMine?"none":"rotate(90deg)",transition:"transform 0.15s"}}>›</span>
        </button>
        {!collapseMine&&mine.map(t=><Row key={t.id} t={t} mineRow/>)}
      </>}
      {byMe.length>0&&<>
        <button onClick={()=>setShowWaiting(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",width:"100%",background:"transparent",border:"none",cursor:"pointer",padding:"9px 0 2px"}}>
          <span style={{fontSize:8.5,color:T.muted,fontWeight:800,letterSpacing:"0.08em",textTransform:"uppercase"}}>Waiting on others ({byMe.length})</span>
          <span style={{fontSize:10,color:T.ghost,transform:showWaiting?"rotate(90deg)":"none",transition:"transform 0.15s"}}>›</span>
        </button>
        {showWaiting&&byMe.map(t=><Row key={t.id} t={t}/>)}
      </>}
      {!adding&&mine.length===0&&byMe.length===0&&<div style={{fontSize:11,color:T.ghost,fontStyle:"italic",paddingTop:4}}>Nothing assigned — tap + Assign Task to send someone a to-do.</div>}
      </>}
    </div>
  );
}

// ─── CLOSINGS · NEXT 7 DAYS — rolling window from today, tap a loan for where & when ───
function ClosingThisWeek({leads,loans,T,HL,onSaveDetails,onFund,onDismiss}) {
  const [openId,setOpenId]=useState(null);
  const [dTime,setDTime]=useState(""); const [dLoc,setDLoc]=useState(""); const [dNotes,setDNotes]=useState(""); const [dDate,setDDate]=useState("");
  // Rolling window: today through six days out, recomputed on every render and
  // re-checked on a timer so a session left open overnight rolls to the new day.
  const [tick,setTick]=useState(0);
  useEffect(()=>{ const iv=setInterval(()=>setTick(t=>t+1), 10*60*1000);
    const onVis=()=>{ if(document.visibilityState==="visible") setTick(t=>t+1); };
    document.addEventListener("visibilitychange",onVis);
    return ()=>{ clearInterval(iv); document.removeEventListener("visibilitychange",onVis); };
  },[]);
  const today=new Date(); today.setHours(0,0,0,0);
  const mon=today;
  const fri=new Date(today); fri.setDate(today.getDate()+6);
  const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  const a=iso(mon), b=iso(fri), todayIso=iso(today);
  const seen=new Set();
  const events=[
    ...leads.filter(l=>l.closingDate&&!["ghosted","archived","creditrepair","onhold"].includes(l.stage)),
    ...loans.filter(l=>l.closingDate&&l.stage==="closed"&&!l._fromLead&&!l.closingDismissed),
  ].filter(l=>{ if(l.closingDate<a||l.closingDate>b||seen.has(l.id)) return false; seen.add(l.id); return true; })
   .sort((x,y)=>{ const d=x.closingDate.localeCompare(y.closingDate); if(d) return d;
     const t=s=>{ const m=/(\d{1,2}):?(\d{2})?\s*(a|p)/i.exec(s||""); if(!m) return 9999; let h=parseInt(m[1])%12; if(/p/i.test(m[3])) h+=12; return h*60+(parseInt(m[2])||0); };
     return t(x.closingTime)-t(y.closingTime); });
  const fmtK=v=>v>=1000000?`$${(v/1000000).toFixed(1)}M`:v>0?`$${Math.round(v/1000)}K`:"TBD";
  const vol=events.reduce((s2,l)=>s2+(l.loanAmount||l.amount||0),0);
  const rng=`${mon.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${fri.toLocaleDateString("en-US",{month:"short",day:"numeric"})}`;   // eslint-disable-line no-unused-vars
  const open=l=>{ if(openId===l.id){setOpenId(null);return;} setOpenId(l.id); setDDate(l.closingDate||""); setDTime(l.closingTime||""); setDLoc(l.closingLocation||""); setDNotes(l.closingNotes||""); };
  const save=l=>{ onSaveDetails(l,{date:dDate,time:dTime,location:dLoc,notes:dNotes}); setOpenId(null); };
  const inp={width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"7px 10px",color:T.text,fontSize:12,outline:"none"};
  return (
    <div style={{margin:"0 16px 14px",borderRadius:10,overflow:"hidden",border:`1px solid ${T.border}`,background:T.card}}>
      <div style={{padding:"12px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div style={{fontSize:12,fontWeight:800,color:T.text2,letterSpacing:"0.04em",textTransform:"uppercase"}}>Closings · Next 7 Days</div>
        <div style={{fontSize:10.5,color:T.muted,fontWeight:700}}>{rng}{events.length>0?` · ${events.length} unit${events.length!==1?"s":""} · ${fmtK(vol)}`:""}</div>
      </div>
      {events.length===0&&<div style={{padding:"13px 16px",fontSize:12,color:T.ghost,fontStyle:"italic"}}>No closings scheduled in the next 7 days.</div>}
      {events.map((l,i)=>{
        const isToday=l.closingDate===todayIso;
        const isFunded=l.stage==="closed";
        const dn=new Date(l.closingDate+"T12:00").toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"});
        const amt=l.loanAmount||l.amount||0;
        const expanded=openId===l.id;
        return (
          <div key={l.id} style={{borderBottom:i<events.length-1||expanded?`1px solid ${T.border}`:"none",background:isFunded?"rgba(16,140,70,0.10)":isToday?`${HL.border}0d`:"transparent",borderLeft:isFunded?"3px solid #0a6b34":"3px solid transparent"}}>
            <div onClick={()=>open(l)} style={{padding:"12px 16px",display:"flex",justifyContent:"space-between",alignItems:"center",cursor:"pointer",gap:10}}>
              {isFunded
                ? <span onClick={e=>{e.stopPropagation();onDismiss&&onDismiss(l);}} title="Funded — tap to clear from dashboard (stays in Funded database)" style={{width:22,height:22,borderRadius:6,flexShrink:0,background:"#0a6b34",color:"#fff",fontSize:12,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",border:"2px solid #0a6b34"}}>✓</span>
                : onFund&&<span onClick={e=>{e.stopPropagation();if(window.confirm(`Mark ${l.name||l.borrower} as Closed & Funded? Moves to the Funded database.`)) onFund(l);}} title="Tap when closed & funded" style={{width:22,height:22,borderRadius:11,flexShrink:0,border:`2px solid ${T.muted}66`,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}/>}
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontSize:14,fontWeight:700,color:isFunded?"#0a6b34":T.text,display:"flex",alignItems:"center",gap:7}}>
                  {l.name||l.borrower}
                  {isFunded&&<span style={{fontSize:8,fontWeight:900,color:"#fff",background:"#0a6b34",borderRadius:4,padding:"2px 6px",letterSpacing:"0.05em"}}>FUNDED · ✓ to clear</span>}
                  {!isFunded&&isToday&&<span style={{fontSize:8,fontWeight:900,color:"#fff",background:HL.border,borderRadius:4,padding:"2px 6px",letterSpacing:"0.05em"}}>TODAY</span>}
                </div>
                <div style={{fontSize:11,color:T.muted,marginTop:2}}>{dn}{l.closingTime?` · ${l.closingTime}`:""}{l.loanType?` · ${l.loanType}`:""}</div>
                {l.closingLocation&&<div style={{fontSize:10.5,color:T.text2,marginTop:2,fontWeight:600}}>📍 {l.closingLocation}</div>}
              </div>
              <div style={{display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
                <div style={{fontSize:13,fontWeight:700,color:T.text}}>{fmtK(amt)}</div>
                <div style={{fontSize:11,color:T.ghost,transform:expanded?"rotate(90deg)":"none",transition:"transform 0.15s"}}>›</div>
              </div>
            </div>
            {expanded&&(
              <div style={{padding:"0 16px 13px",display:"flex",flexDirection:"column",gap:7}}>
                <div style={{display:"flex",gap:7}}>
                  <div style={{flex:1.2}}><div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Closing Date</div><input type="date" value={dDate} onChange={e=>setDDate(e.target.value)} style={{...inp,padding:"6px 8px"}}/></div>
                  <div style={{flex:1}}><div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Time</div><input value={dTime} onChange={e=>setDTime(e.target.value)} placeholder="10:00 AM" style={inp}/></div>
                  <div style={{flex:2}}><div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Where</div><input value={dLoc} onChange={e=>setDLoc(e.target.value)} placeholder="Title company / attorney office" style={inp}/></div>
                </div>
                <div><div style={{fontSize:8.5,color:T.muted,fontWeight:800,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:3}}>Notes</div><input value={dNotes} onChange={e=>setDNotes(e.target.value)} placeholder="Cashier's check amount, gate code…" style={inp}/></div>
                <button onClick={()=>save(l)} style={{background:T.navy,border:"none",borderRadius:8,padding:"8px 0",color:"#fff",fontWeight:800,fontSize:11,cursor:"pointer"}}>Save Closing Details</button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

