// ─── CONSTANTS ────────────────────────────────────────────────────────────────
// ── TITLE COMPANY FEE PRESETS ──
// Blake: send per-company costs and they go here. Blank "" = leave that field untouched.
// Keys: closing (Closing Fee), cpl (Protection Ltr), courier, endorse (Endorsements), exam, ltitle (Lender's Title — blank keeps auto)
const KY_CITY_COUNTY = { "harrodsburg":"Mercer","burgin":"Mercer","danville":"Boyle","perryville":"Boyle","junction city":"Boyle","stanford":"Lincoln","crab orchard":"Lincoln","hustonville":"Lincoln","waynesburg":"Lincoln","lancaster":"Garrard","paint lick":"Garrard","lexington":"Fayette","nicholasville":"Jessamine","wilmore":"Jessamine","richmond":"Madison","berea":"Madison","somerset":"Pulaski","liberty":"Casey","lebanon":"Marion","springfield":"Washington","versailles":"Woodford","georgetown":"Scott","frankfort":"Franklin","winchester":"Clark","harrodsburg ":"Mercer","salvisa":"Mercer","louisville":"Jefferson" };
const KY_PVA_URL = (county) => {
  const c = String(county||"").toLowerCase();
  if (c==="fayette") return "https://fayettepva.com";
  if (c==="jefferson") return "https://jeffersonpva.ky.gov";
  return c ? `https://www.qpublic.net/ky/${c}/` : "https://www.qpublic.net/ky/";
};
const detectKyCounty = (address) => {
  const a = String(address||"").toLowerCase();
  for (const city of Object.keys(KY_CITY_COUNTY)) if (a.includes(city)) return KY_CITY_COUNTY[city];
  return "";
};
// Fixed fees pulled from actual closing disclosures (Aug 2025 - Jul 2026).
// ltitleRate is the lender's policy as a % of loan amount, derived from those same
// files — title premium is a filed rate, not a flat fee, so it must scale.
// Refis run cheaper than purchases (reissue), which is why Land Group's rate is lower.
const TITLE_FEE_PRESETS = {
  "The Land Group":         { closing:"595", cpl:"50", courier:"45", endorse:"", exam:"100", ltitle:"798",
                              ltitleRate:0.00311, muniPct:0.06, note:"Somerset city premium tax applies · $10 filing fee" },
  "Bluegrass Land Title":   { closing:"250", cpl:"50", courier:"", endorse:"", exam:"", ltitle:"1105",
                              ltitleRate:0.00409, muniPct:0.09, settle:"650", deedPrep:"250",
                              note:"Closing $250 + settlement $650 · Frankfort city premium tax applies" },
  "Five Star Land Title":   { closing:"475", cpl:"50", courier:"35", endorse:"", exam:"400", ltitle:"808",
                              ltitleRate:0.00436, wire:"25", signing:"75", recording:"35",
                              note:"Closing $475 \u00b7 doc signing $75 \u00b7 wire $25 \u00b7 recording svc $35 \u00b7 policy via Westcor" },
  "Kentucky Abstract Title":{ closing:"400", cpl:"50", courier:"60", endorse:"50", exam:"400", ltitle:"1358",
                              ltitleRate:0.00377, note:"Deed prep billed separately by attorney (~$150)" },
  "T.E.C.E. Title Services":{ closing:"200", cpl:"50", courier:"75", endorse:"50", exam:"450", ltitle:"445",
                              ltitleRate:0.00305, wire:"60", deedPrep:"100",
                              note:"Commitment fee $450 · endorsements $50 each · wire in/out $30 each" },
};
// Lender's title premium scales with the loan. Falls back to the flat figure if unknown.
const titlePremium = (company, loanAmount) => {
  const p = TITLE_FEE_PRESETS[company];
  if(!p) return null;
  const amt = Number(loanAmount)||0;
  if(p.ltitleRate && amt>0) return Math.round(amt * p.ltitleRate);
  return p.ltitle ? Number(p.ltitle) : null;
};
