// Program buckets for counting. Labels drift over the years ("Rural Development", "RD",
// "FHA/USDA"), so every record is normalized here — FHA and USDA stay distinct, and any
// unrecognized label lands in Other rather than vanishing from the totals.
// Home-sale contingency marker — deliberately loud, since it changes how a file is worked.
function ContBadge({on, T, size}){
  if(!on) return null;
  const sm = size==="sm";
  return <span title="Home sale contingency — buyer must sell their current home" style={{display:"inline-block",background:"rgba(138,28,28,0.10)",border:"1px solid #8a1c1c",color:"#8a1c1c",borderRadius:4,padding:sm?"0 3px":"0 4px",fontSize:sm?8.5:9.5,fontWeight:900,letterSpacing:"0.02em",marginLeft:5,verticalAlign:"baseline",lineHeight:1.45}}>C</span>;
}
function loanBucket(t){
  const x = String(t||"").trim();
  if(!x) return "Unlabeled";
  const u = x.toUpperCase();
  if(/FHA\s*\/\s*USDA|USDA\s*\/\s*FHA/.test(u)) return "FHA/USDA (needs split)";
  const khc    = /\bKHC\b|KENTUCKY HOUSING/.test(u);
  const isUSDA = /USDA|RURAL DEV|\bRD\b|GUARANTEED RURAL/.test(u);
  const isFHA  = /\bFHA\b/.test(u);
  const isVA   = /\bVA\b|VETERAN/.test(u);
  if(khc){
    if(isUSDA) return "KHC USDA";
    if(isFHA)  return "KHC FHA";
    if(isVA)   return "KHC VA";
    return "KHC CONV";
  }
  if(isUSDA) return "USDA";
  if(isFHA)  return "FHA";
  if(isVA)   return "VA";
  if(/JUMBO/.test(u)) return "Jumbo";
  if(/NON.?QM/.test(u)) return "Non-QM";
  if(/CONV|FANNIE|FREDDIE/.test(u)) return "Conventional";
  return "Other";
}
