function LoginScreen({T, onDone}) {
  const [email,setEmail] = useState("");
  const [pw,setPw] = useState("");
  const [busy,setBusy] = useState(false);
  const [err,setErr] = useState("");
  const go = async () => {
    if (!email || !pw) { setErr("Email and password required"); return; }
    setBusy(true); setErr("");
    try { await authSignIn(email, pw); onDone && onDone(); }
    catch(e){ setErr(String(e?.message||e).replace(/^AuthApiError:\s*/,"")); }
    setBusy(false);
  };
  const W = {width:"100%",boxSizing:"border-box",background:T.card,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"11px 13px",color:T.text,fontSize:14,outline:"none",marginBottom:9};
  return (
    <div style={{minHeight:"100vh",background:T.page,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",fontFamily:"'Inter',system-ui,sans-serif",padding:24}}>
      <div style={{fontSize:20,fontWeight:900,color:T.text,fontFamily:"Georgia,serif",letterSpacing:"0.02em",textShadow:"0 0 26px rgba(201,162,39,0.22), 0 0 70px rgba(201,162,39,0.08)"}}>HENDERSON TEAM</div>
      <div style={{fontSize:8.5,color:T.text2,fontWeight:800,letterSpacing:"0.22em",textTransform:"uppercase",marginTop:6,marginBottom:22}}>Reputation · Service · Results</div>
      <div style={{width:"100%",maxWidth:320}}>
        <input value={email} onChange={e=>setEmail(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")go();}} type="email" autoComplete="username" placeholder="Email" style={W}/>
        <input value={pw} onChange={e=>setPw(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")go();}} type="password" autoComplete="current-password" placeholder="Password" style={W}/>
        {err&&<div style={{fontSize:11,color:"#d81f2a",fontWeight:700,marginBottom:8,lineHeight:1.4}}>{err}</div>}
        <button onClick={go} disabled={busy} style={{width:"100%",background:busy?T.border:T.navy,border:"none",borderRadius:10,padding:"12px 0",color:"#fff",fontWeight:900,fontSize:13.5,cursor:busy?"default":"pointer"}}>{busy?"Signing in…":"Sign In"}</button>
        <div style={{fontSize:10,color:T.ghost,textAlign:"center",marginTop:12,lineHeight:1.5}}>Team and partner agents use the same door — your account decides what you see.</div>
      </div>
    </div>
  );
}
function PassLock({T, title, onUnlock}) {
  const [pw,setPw] = useState("");
  const stored = (()=>{ try { return localStorage.getItem("pnlPass"); } catch { return null; } })();
  const go = () => {
    if (!stored) { if (pw.length<4) { alert("4+ characters"); return; } try{ localStorage.setItem("pnlPass", btoa(pw)); }catch{} onUnlock(); }
    else if (btoa(pw)===stored) onUnlock();
    else alert("Wrong passcode");
  };
  return (
    <div style={{padding:"56px 24px",display:"flex",justifyContent:"center"}}>
      <div style={{maxWidth:340,width:"100%",background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:"24px 20px",textAlign:"center"}}>
        <div style={{fontSize:26,marginBottom:8}}>🔒</div>
        <div style={{fontSize:15,fontWeight:800,color:T.text,marginBottom:4}}>{title}</div>
        <div style={{fontSize:10.5,color:T.muted,marginBottom:14}}>{stored?"Enter your passcode — same one as P&L.":"Set a passcode — it will protect P&L and the Database."}</div>
        <input type="password" value={pw} onChange={e=>setPw(e.target.value)} onKeyDown={e=>{ if(e.key==="Enter") go(); }} autoFocus style={{width:"100%",boxSizing:"border-box",background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:9,padding:"10px 12px",color:T.text,fontSize:14,outline:"none",textAlign:"center",letterSpacing:"0.2em"}}/>
        <button onClick={go} style={{width:"100%",marginTop:10,background:T.navy,border:"none",borderRadius:9,padding:"11px 0",color:"#fff",fontWeight:900,fontSize:12.5,cursor:"pointer"}}>{stored?"Unlock":"Set Passcode"}</button>
      </div>
    </div>
  );
}
function DiagCard({T,leads,loans,currentUser,dataSource,lastSaveRef,pendingWritesRef}) {
  const [live,setLive] = useState(null);
  const [busy,setBusy] = useState(false);
  const ping = async () => {
    setBusy(true);
    try {
      const sb = await getSupabase();
      if (!sb) { setLive({err:"getSupabase returned null — not connected"}); setBusy(false); return; }
      const { count, error } = await sb.from("clients").select("*",{count:"exact",head:true});
      if (error) { setLive({err:error.message}); setBusy(false); return; }
      const { data: recent } = await sb.from("clients").select("name,status,stage").order("created_at",{ascending:false}).limit(3);
      setLive({count, recent:recent||[]});
    } catch(e){ setLive({err:String(e?.message||e)}); }
    setBusy(false);
  };
  const byStage = {};
  leads.forEach(l=>{ byStage[l.stage]=(byStage[l.stage]||0)+1; });
  const rowS = {display:"flex",justifyContent:"space-between",fontSize:11,padding:"2px 0"};
  return (
    <div style={{background:"#0B1F3A",border:"2px solid #C9A227",borderRadius:12,padding:"12px 14px"}}>
      <div style={{fontSize:10,color:T.gold,fontWeight:900,letterSpacing:"0.1em",textTransform:"uppercase",marginBottom:8}}>🔧 Diagnostics — screenshot this card</div>
      <div style={{color:"#fff"}}>
        <div style={rowS}><span>Build</span><b>{BUILD_TAG}</b></div>
        <div style={rowS}><span>User profile</span><b>{currentUser}</b></div>
        <div style={rowS}><span>Data source</span><b style={{color:dataSource==="supabase"?"#7ee2a8":"#ff9d9d"}}>{dataSource}{dataSource!=="supabase"&&" ⚠️ NOT CONNECTED — nothing persists"}</b></div>
        <div style={rowS}><span>Leads in memory</span><b>{leads.length} ({Object.entries(byStage).map(([s,c])=>`${s}:${c}`).join(" ")})</b></div>
        <div style={rowS}><span>Database records</span><b>{loans.length}</b></div>
        <div style={rowS}><span>Pending writes</span><b>{pendingWritesRef.current}</b></div>
        <div style={{...rowS,flexDirection:"column",gap:2}}><span>Last save result</span><b style={{fontSize:10,wordBreak:"break-word"}}>{lastSaveRef.current}</b></div>
        <button onClick={ping} disabled={busy} style={{marginTop:8,width:"100%",background:T.gold,border:"none",borderRadius:8,padding:"9px 0",color:"#0B1F3A",fontWeight:900,fontSize:12,cursor:"pointer"}}>{busy?"Testing…":"⚡ Test Live Database Connection"}</button>
        {live&&(
          <div style={{marginTop:8,fontSize:10.5,background:"rgba(255,255,255,0.08)",borderRadius:8,padding:"8px 10px"}}>
            {live.err
              ? <span style={{color:"#ff9d9d"}}>✗ {live.err}</span>
              : <span style={{color:"#7ee2a8"}}>✓ Connected · {live.count} client rows · newest: {live.recent.map(r=>`${r.name} (${r.status}/${r.stage})`).join(" · ")}</span>}
          </div>
        )}
      </div>
    </div>
  );
}
