            <div style={{flex:1}}><div style={{fontSize:9,color:T.muted,fontWeight:700,textTransform:"uppercase",marginBottom:3}}>Pts Charged</div><input value={pts} onChange={e=>setPts(e.target.value)} placeholder="1" style={inpS}/></div>
