function PreApprovalModal({ lead, T, onClose }) {
  const [config, setConfig] = useState({
    loanAmount:"", purchasePrice:"",
    loName:"Blake Henderson",
    loTitle:"President of Residential Lending",
    loNMLS:"1780946",
    companyName:"New American Funding",
    companyNMLS:"6606",
    phone:"606-669-7648",
    email:"TeamHenderson@naf.com",
    expiryDays:"30",
    extraNote:"",
    loanType: lead.loanType || "",
    loanTypeCustom: "",
    homeSaleContingency: false,
  });
  const [generated, setGenerated] = useState("");
  const [loading, setLoading]     = useState(false);
  const s = (k,v) => setConfig(p=>({...p,[k]:v}));

  const inp = (label, key, ph="") => (
    <div>
      <div style={{fontSize:10,color:T.muted,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:5}}>{label}</div>
      <input value={config[key]} onChange={e=>s(key,e.target.value)} placeholder={ph} style={{boxSizing:"border-box",width:"100%",background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"9px 12px",color:T.text,fontSize:13,outline:"none"}}/>
    </div>
  );

  const generate = async () => {
    setLoading(true);
    const expiry = new Date(); expiry.setDate(expiry.getDate()+parseInt(config.expiryDays||30));
    const expiryStr = expiry.toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"});
    const today = new Date().toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"});
    try {
      const res = await fetch("/api/jarvis",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          model:"claude-sonnet-4-6", max_tokens:1000,
          system:"You are an expert mortgage loan officer assistant. Write professional pre-approval letters. Return ONLY the letter text, no commentary.",
          messages:[{ role:"user", content:`Write a professional mortgage pre-approval letter with these details:
Borrower: ${lead.name}
Loan Amount: ${config.loanAmount}
Purchase Price: ${config.purchasePrice}
Loan Type: ${config.loanType==="Other"?(config.loanTypeCustom||lead.loanType):(config.loanType||lead.loanType)}
Loan Purpose: ${lead.loanPurpose}
Home Sale Contingency: ${config.homeSaleContingency?"Yes - this pre-approval is contingent upon the successful sale and closing of the borrower's current residence. Include a clear sentence stating this contingency in the letter.":"No"}
Date: ${today}
Expiry Date: ${expiryStr}
Loan Officer: ${config.loName}
Title: ${config.loTitle}
LO NMLS: #${config.loNMLS}
Company: ${config.companyName}
Company NMLS: #${config.companyNMLS}
Phone: ${config.phone}
Email: ${config.email}
Equal Housing Lender
Additional Note: ${config.extraNote||"None"}

Write a clean, professional pre-approval letter. Include all standard mortgage pre-approval language. At the bottom include the loan officer signature block with their name, title, NMLS number, company name, company NMLS, phone, email, and "Equal Housing Lender" designation. Format with proper paragraphs.`
          }]
        })
      });
      const data = await res.json();
      setGenerated(data.content?.[0]?.text||"");
    } catch { setGenerated("Error generating letter. Please try again."); }
    setLoading(false);
  };

  const copy = () => { navigator.clipboard?.writeText(generated); };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:T.card,borderRadius:16,width:"100%",maxWidth:540,maxHeight:"92vh",overflowY:"auto",border:`1px solid ${T.border}`}}>
        <div style={{padding:"18px 20px 14px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
          <div>
            <div style={{fontSize:10,color:T.gold,fontWeight:800,letterSpacing:"0.08em",textTransform:"uppercase"}}>Pre-Approval Letter</div>
            <div style={{fontSize:17,fontWeight:800,color:T.text,marginTop:2}}>{fmtName(lead.name)}</div>
          </div>
          <button onClick={onClose} style={{background:T.inner,border:"none",color:T.muted,borderRadius:8,padding:"6px 10px",cursor:"pointer",fontSize:18}}>×</button>
        </div>
        <div style={{padding:20,display:"flex",flexDirection:"column",gap:12}}>
          {!generated ? (
            <>
              <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                <div style={{flex:1}}>{inp("Loan Amount","loanAmount","$485,000")}</div>
                <div style={{flex:1}}>{inp("Purchase Price","purchasePrice","$550,000")}</div>
              </div>
              <div>
                <div style={{fontSize:10,color:T.muted,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:6}}>Loan Type</div>
                <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                  {["FHA","Conventional","VA","USDA","FHA KHC","Conventional KHC","Other"].map(opt=>(
                    <button key={opt} onClick={()=>s("loanType",opt)} style={{padding:"7px 12px",borderRadius:20,fontSize:12,fontWeight:600,cursor:"pointer",background:config.loanType===opt?T.navy:T.inner,color:config.loanType===opt?"white":T.muted,border:config.loanType===opt?"none":`1px solid ${T.border}`}}>{opt}</button>
                  ))}
                </div>
                {config.loanType==="Other" && (
                  <input value={config.loanTypeCustom} onChange={e=>s("loanTypeCustom",e.target.value)} placeholder="Enter loan type" style={{boxSizing:"border-box",width:"100%",marginTop:8,background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:8,padding:"9px 12px",color:T.text,fontSize:13,outline:"none"}}/>
                )}
              </div>
              <div onClick={()=>s("homeSaleContingency",!config.homeSaleContingency)} style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer",background:T.inner,borderRadius:8,padding:"10px 12px",border:`1px solid ${config.homeSaleContingency?T.navy:T.border}`}}>
                <div style={{width:18,height:18,borderRadius:4,border:`2px solid ${config.homeSaleContingency?T.navy:T.border}`,background:config.homeSaleContingency?T.navy:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  {config.homeSaleContingency && <span style={{color:"#fff",fontSize:12,fontWeight:900}}>✓</span>}
                </div>
                <span style={{fontSize:13,color:T.text,fontWeight:600}}>Home sale contingency</span>
              </div>
              <div style={{background:T.inner,borderRadius:10,padding:"10px 14px",border:`1px solid ${T.border}`}}>
                <div style={{fontSize:10,color:T.gold,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:8}}>Loan Officer Info</div>
                <div style={{display:"flex",flexDirection:"column",gap:10}}>
                  {inp("LO Name","loName")}
                  {inp("Title","loTitle")}
                  <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                    <div style={{flex:1}}>{inp("LO NMLS #","loNMLS","NMLS #")}</div>
                    <div style={{flex:1}}>{inp("Company NMLS","companyNMLS","NMLS #")}</div>
                  </div>
                  {inp("Company Name","companyName")}
                  <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
                    <div style={{flex:1}}>{inp("Phone","phone")}</div>
                    <div style={{flex:1}}>{inp("Email","email")}</div>
                  </div>
                  {inp("Expiry (days)","expiryDays","30")}
                  <div style={{background:`${T.navy}18`,borderRadius:8,padding:`8px 12px`,border:`1px solid ${T.navy}33`}}>
                    <div style={{fontSize:10,color:T.navy,fontWeight:700}}>⚖ Equal Housing Lender · Auto-included in letter</div>
                  </div>
                </div>
              </div>
              {inp("Additional Note (optional)","extraNote","Any special conditions or notes...")}
              <button onClick={generate} disabled={loading||!config.loanAmount} style={{background:T.navy,border:`1px solid ${T.gold}44`,borderRadius:10,padding:"12px",color:T.text,fontWeight:700,fontSize:14,cursor:"pointer",marginTop:4}}>
                {loading?"Generating Letter...":"✦ Generate Pre-Approval Letter"}
              </button>
            </>
          ) : (
            <>
              <div style={{background:T.inner,borderRadius:10,padding:16,border:`1px solid ${T.border}`,fontSize:12,color:T.text2,lineHeight:1.8,whiteSpace:"pre-wrap",fontFamily:"Georgia,serif"}}>
                {generated}
              </div>
              <div style={{display:"flex",gap:8}}>
                <button onClick={()=>setGenerated("")} style={{flex:1,background:T.inner,border:`1px solid ${T.border}`,borderRadius:10,padding:"10px",color:T.muted,fontWeight:700,fontSize:13,cursor:"pointer"}}>← Edit</button>
                <button onClick={copy} style={{flex:2,background:T.navy,border:`1px solid ${T.gold}44`,borderRadius:10,padding:"10px",color:T.text,fontWeight:700,fontSize:13,cursor:"pointer"}}>Copy Letter</button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── AI DRAWER ────────────────────────────────────────────────────────────────
function AIDrawer({ context, title, subtitle, T, onClose }) {
  const [messages, setMessages] = useState([{ role:"assistant", text:`Pulled up ${title}${subtitle?` — ${subtitle}`:""}.  What do you need?` }]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef(null);

  const send = async () => {
    if (!input.trim()||loading) return;
    const msg = input.trim(); setInput("");
    setMessages(m=>[...m,{role:"user",text:msg}]); setLoading(true);
    try {
      const history = messages.filter((_,i)=>i>0).map(m=>({role:m.role,content:m.text}));
      const res = await fetch("/api/jarvis",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1000,system:`You are an AI assistant for the Henderson Team mortgage pipeline. Context:\n${context}\n\nBe concise, practical, professional.`,messages:[...history,{role:"user",content:msg}]})});
      const data = await res.json();
      setMessages(m=>[...m,{role:"assistant",text:data.content?.[0]?.text||"No response."}]);
    } catch { setMessages(m=>[...m,{role:"assistant",text:"Connection error."}]); }
    setLoading(false);
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.65)",zIndex:300,display:"flex",alignItems:"flex-end",justifyContent:"center"}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:T.card,borderRadius:"20px 20px 0 0",width:"100%",maxWidth:520,height:"70vh",display:"flex",flexDirection:"column",border:`1px solid ${T.border}`,borderBottom:"none"}}>
        <div style={{padding:"16px 20px 12px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <div>
            <div style={{fontSize:11,color:T.gold,fontWeight:800,letterSpacing:"0.08em",textTransform:"uppercase"}}>✦ AI Assistant</div>
            <div style={{fontSize:15,color:T.text,fontWeight:600,marginTop:2}}>{title}</div>
          </div>
          <button onClick={onClose} style={{background:T.inner,border:"none",color:T.muted,borderRadius:8,padding:"6px 12px",cursor:"pointer",fontSize:13}}>Close</button>
        </div>
        <div style={{flex:1,overflowY:"auto",padding:"14px 18px",display:"flex",flexDirection:"column",gap:10}}>
          {messages.map((m,i)=>(
            <div key={i} style={{display:"flex",justifyContent:m.role==="user"?"flex-end":"flex-start"}}>
              <div style={{maxWidth:"84%",padding:"10px 14px",borderRadius:m.role==="user"?"14px 14px 4px 14px":"14px 14px 14px 4px",background:m.role==="user"?T.navy:T.inner,color:T.text,fontSize:13,lineHeight:1.55,whiteSpace:"pre-wrap"}}>{m.text}</div>
            </div>
          ))}
          {loading && <div style={{display:"flex",gap:5,padding:"8px 14px"}}>{[0,1,2].map(i=><div key={i} style={{width:6,height:6,borderRadius:"50%",background:T.gold,animation:`dot 1.2s ${i*0.2}s infinite`}}/>)}</div>}
          <div ref={bottomRef}/>
        </div>
        <div style={{padding:"10px 14px",borderTop:`1px solid ${T.border}`,display:"flex",gap:8}}>
          <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder="Ask anything..." style={{flex:1,background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"10px 14px",color:T.text,fontSize:13,outline:"none"}}/>
          <button onClick={send} disabled={loading} style={{background:T.navy,border:"none",borderRadius:10,padding:"10px 16px",color:T.text,fontWeight:700,fontSize:14,cursor:"pointer"}}>→</button>
        </div>
      </div>
    </div>
  );
}

// ─── SHARED UI ────────────────────────────────────────────────────────────────
const SLabel = ({children,T}) => <div style={{fontSize:11,color:T.muted,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:8}}>{children}</div>;

function NoteInput({notes,onAdd,onDelete,T,onDraft}) {
  const [text,setText] = useState("");
  const setT = v => { setText(v); if(onDraft) onDraft(v); };
  const [notesOpen,setNotesOpen] = useState((notes||[]).length<5);
  const noteList = notes||[];
  return (
    <div>
      <div onClick={()=>setNotesOpen(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer"}}>
        <SLabel T={T}>Team Notes ({noteList.length})</SLabel>
        <span style={{fontSize:11,color:T.ghost,transform:notesOpen?"rotate(90deg)":"none",transition:"transform 0.15s"}}>›</span>
      </div>
      {notesOpen && <div style={{display:"flex",flexDirection:"column",gap:4,marginBottom:8,maxHeight:150,overflowY:"auto",paddingRight:2}}>
        {noteList.length===0 && <div style={{fontSize:13,color:T.ghost,fontStyle:"italic"}}>No notes yet.</div>}
        {noteList.map((n,i)=>(
          <div key={i} style={{background:T.inner,borderRadius:6,padding:"3px 8px",display:"flex",alignItems:"baseline",gap:6}}>
            <div style={{flex:1,minWidth:0,fontSize:10.5,lineHeight:1.35}}>
              <span style={{fontWeight:800,color:T.text}}>{n.author}:</span>{" "}
              <span style={{color:T.text2}}>{n.text}</span>
            </div>
            <span style={{fontSize:8.5,color:T.ghost,flexShrink:0,whiteSpace:"nowrap"}}>{n.time||""}</span>
            {onDelete && <button onClick={()=>onDelete(i)} style={{background:"transparent",border:"none",color:T.red,cursor:"pointer",fontSize:11,padding:"0 1px",lineHeight:1,flexShrink:0}}>✕</button>}
          </div>
        ))}
      </div>}
      <div style={{display:"flex",gap:8}}>
        <input value={text} onChange={e=>setT(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&text.trim()){onAdd(text.trim());setT("");}}} placeholder="Add a note..." style={{flex:1,background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"10px 14px",color:T.text,fontSize:13,outline:"none"}}/>
        <button onClick={()=>{if(text.trim()){onAdd(text.trim());setT("");}}} style={{background:text.trim()?T.navy:T.inner,border:text.trim()?"none":`1px solid ${T.inputBorder}`,borderRadius:10,padding:"10px 16px",color:text.trim()?"#fff":T.text2,cursor:"pointer",fontSize:12.5,fontWeight:800,whiteSpace:"nowrap"}}>+ Add</button>
      </div>
    </div>
  );
}

