const smartYearDate = (month, day) => {
  const now = new Date();
  let y = now.getFullYear();
  let d = new Date(y, month-1, day);
  // a "closing" more than 30 days in the past must mean next year
  if (d < new Date(now.getFullYear(), now.getMonth(), now.getDate() - 30)) y += 1;
  return `${y}-${String(month).padStart(2,"0")}-${String(day).padStart(2,"0")}`;
};
const MonthDayPicker = ({value,onChange,T,label="Closing Date"}) => {
  const m = value ? parseInt(value.slice(5,7)) : 0;
  const d = value ? parseInt(value.slice(8,10)) : 0;
  const y = value ? value.slice(0,4) : "";
  const MO = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const days = m ? new Date(2028, m, 0).getDate() : 31;
  const inp = {boxSizing:"border-box",background:T.inner,border:`1px solid ${T.inputBorder}`,borderRadius:9,padding:"9px 8px",color:T.text,fontSize:13,fontWeight:700,outline:"none"};
  const set = (mm,dd) => { if(mm&&dd) onChange(smartYearDate(mm,dd)); };
  return (
    <div>
      <div style={{fontSize:10,color:T.muted,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",marginBottom:5}}>{label}{y?<span style={{color:T.ghost,fontWeight:600}}> · {y}</span>:null}</div>
      <div style={{display:"flex",gap:7}}>
        <select value={m||""} onChange={e=>set(parseInt(e.target.value)||0, d||1)} style={{...inp,flex:1.3}}>
          <option value="">Month</option>
          {MO.map((mo,i)=><option key={mo} value={i+1}>{mo}</option>)}
        </select>
        <select value={d||""} onChange={e=>set(m||new Date().getMonth()+1, parseInt(e.target.value)||0)} style={{...inp,flex:1}}>
          <option value="">Day</option>
          {Array.from({length:days},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}
        </select>
        {value&&<button onClick={()=>onChange("")} style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:9,padding:"0 11px",color:T.ghost,cursor:"pointer",fontSize:14}}>×</button>}
      </div>
    </div>
  );
};
