  const rec = { id:src.id, name:src.name, phone:src.phone, status:"pipeline", milestones:src.milestones||{},
    todos:[{t:"Last 2 bank statements",done:false},{t:"Homeowners insurance quote",done:false}],
    titleCompany:"Bluegrass Land Title", agent:src.realtorAgent||"", address:src.address||"", city:src.city||"", state:src.state||"", zip:src.zip||"",
    loanType:src.loanType||"", amount:src.loanAmount||src.amount||0, rate:src.rate||0, purchasePrice:src.purchasePrice||0,
    closingDate:src.closingDate||"", closingTime:"2:00 PM", closingLocation:"Bluegrass Land Title, Stanford" };
  return (<><PortalPolish/><div><BorrowerStatusPage previewRec={rec} onClosePreview={back}/></div>{bar}<PortalSwitch active={kind==="agent"?"agent":"client"}/></>);
