      const { data:ags, error } = await sb.from("partners").select("*");
      if(error){ setErrMsg("Portal isn’t set up yet."); setPhase("err"); return; }
      const a=(ags||[]).find(x=>String(x.portal_slug||"").toLowerCase()===String(slug).toLowerCase());
      if(!a||!a.portal_on){ setErrMsg("This portal link isn’t active."); setPhase("err"); return; }
      const ptn={ id:a.id||a.name, name:a.name, portalOn:true, portalCap:a.portal_cap||0, portalTypes:a.portal_types||"", portalDays:a.portal_days||0,
        email:String(a.email||"").trim().toLowerCase(), phone:a.phone||"", photoUrl:a.photo_url||"", brokerage:a.brokerage||"", mls:a.mls||"", pin:String(a.portal_pin||""), __live:true };
      setPartner(ptn);
