function bnplLine(fd){
  const n = Math.max(0, parseInt(fd.transactions)||0);
  const tot = Number(fd.total)||0;
  const dates = fd.first_date ? ` ${fd.first_date}${fd.last_date&&fd.last_date!==fd.first_date?`–${fd.last_date}`:""}` : "";
  return `${fd.provider||"Unknown"}${fd.type&&fd.type!=="BNPL"?` (${fd.type})`:" BNPL"} — ${n} debit${n===1?"":"s"}${dates}${tot>0?` totaling $${tot.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`:""}${fd.recurring?" · recurring":""}`;
}
function parseBankScan(raw){
  try{
    const clean = String(raw||"").replace(/```json|```/g,"").trim();
    const j = JSON.parse(clean);
    const list = Array.isArray(j.findings) ? j.findings : [];
    const findings = list.map(fd=>({
      provider: String(fd?.provider||"Unknown"),
      type: String(fd?.type||"BNPL"),
      transactions: Math.max(0, parseInt(fd?.transactions)||0),
      total: Number(fd?.total)||0,
      first_date: String(fd?.first_date||""),
      last_date: String(fd?.last_date||""),
      samples: (Array.isArray(fd?.samples)?fd.samples:[]).slice(0,3).map(x2=>String(x2)),
      recurring: !!fd?.recurring,
    }));
    return { ok:true, findings, none: findings.length===0, notes:String(j?.notes||""), stmt:(j?.statement&&typeof j.statement==="object")?j.statement:{} };
  } catch { return { ok:false, findings:[], none:false, notes:"", stmt:{} }; }
}
