function parseContract(raw){
  try{
    const clean = String(raw||"").replace(/```json|```/g,"").trim();
    const i = clean.indexOf("{"), j = clean.lastIndexOf("}");
    if(i<0||j<i) return {ok:false};
    const o = JSON.parse(clean.slice(i,j+1));
    const F = Array.isArray(o.fields) ? o.fields.filter(x=>x&&x.label&&x.value!=null&&String(x.value).trim()!=="") : [];
    return { ok:true, fields:F.map(x=>({label:String(x.label).slice(0,48), value:String(x.value).slice(0,140), note:String(x.note||"").slice(0,160)})),
      flags: Array.isArray(o.flags) ? o.flags.filter(Boolean).map(x=>String(x).slice(0,200)) : [] };
  }catch{ return {ok:false}; }
}
