  const [tabIds,setTabIds] = useState(()=>tabsRef.current.tabs.map(t=>t.id));
  const sv = (tabsRef.current.tabs.find(t=>t.id===tabsRef.current.activeId)||{}).data || null;
  const blankOpt = (label) => ({ label, price:"", payoff:"", payoff2:"", cashOut:"", loanMan:"", rollCosts:true, armStruct:"", armCaps:"2/1/5", armMargin:"", loanType:"Conventional", downMode:"%", down:"5", rate:"", term:"30", taxes:"", hoi:"", mi:"", hoa:"", buyType:"None", buyCost:"", buySellerPaid:true, fhaMip:"0.55", vaUse:"first", finUp:true, bond:"", bondPmt:"", fees:{orig:"",admin:"",lender:"1995",points:"",miup:"",appraisal:"",credit:"117",eclose:"50",flood:"6",verif:"399",finalinsp:"",ibts:"200",closing:"400",cpl:"50",courier:"60",endorse:"50",exam:"399",ltitle:"",recording:"176",prepaids:"",misc:""}, credits:{seller:"",proration:"",earnest:"",lenderCredit:""} });
