  const nextMonthName = new Date(now.getFullYear(),now.getMonth()+1,1).toLocaleString("default",{month:"long"});
  const inMonth = (dateStr,mo,yr) => { if(!dateStr) return false; const d=new Date(dateStr+"T12:00:00"); return d.getMonth()===mo&&d.getFullYear()===yr; };
  const sixMonthsAgo = new Date(); sixMonthsAgo.setMonth(sixMonthsAgo.getMonth()-6);
  const isRefi = l => { const threshold=refiRates[l.loanType]||6.75; const snoozed=l.refiSnoozed&&(!l.refiSnoozeUntil||new Date(l.refiSnoozeUntil)>now); return l.stage==="closed"&&l.rate>threshold&&l.closingDate&&new Date(l.closingDate)<=sixMonthsAgo&&!snoozed; };

